#include <iostream>
#include <cstdio>
#include <cstring>
#include <algorithm>
using namespace std;

const int mod = 1000000007;
const int maxn = 1000;

int n, m, k;
long long mul[1010], inv[1010], mulinv[1010];
long long f[1010][1010];

long long power(long long x, long long p) {
    long long ret = 1;
    while (p) {
        if (p & 1) {
            ret = ret * x % mod;
        }
        x = x * x % mod;
        p >>= 1;
    }
    return ret;
}

long long c(int a, int b) {
    if (a < 0 || b < 0 || a < b) return 0;
    if (b == 0 || a == b) return 1;
    return mul[a] * mulinv[b] % mod * mulinv[a - b] % mod;
}

int main() {
    mul[0] = 1;
    mulinv[0] = 1;
    mul[1] = 1;
    inv[1] = 1;
    mulinv[1] = 1;

    for (int i = 2; i <= maxn; i++) {
        mul[i] = mul[i - 1] * i % mod;
        inv[i] = (mod - mod / i) * inv[mod % i] % mod;
        mulinv[i] = mulinv[i - 1] * inv[i] % mod;
    }

    f[0][0] = 1;
    for (int i = 1; i <= maxn; i++) {
        for (int j = 1; j <= i; j++) {
            f[i][j] = (j * f[i - 1][j] % mod + f[i - 1][j - 1]) % mod;
        }
    }

    scanf("%d%d%d", &n, &m, &k);

    if (m == 1) {
        printf("%lld\n", power(k, n));
        return 0;
    }

    long long ans = 0;
    for (int i = 1; i <= min(n, k); i++) {
        long long Mul = 1;
        for (int j = 0; j < i; j++) {
            Mul = Mul * (k - j) % mod;
        }

        Mul = Mul * f[n][i] % mod;
        long long mul2 = 1;

        for (int j = i; j >= 0; j--) {
            ans = (ans + Mul * c(i, j) % mod * mul2 % mod
                         * mulinv[i - j] % mod * mul[i] % mod
                         * f[n][i] % mod
                         * power(j, 1LL * (m - 2) * n) % mod) % mod;
            mul2 = mul2 * (k - i - (i - j)) % mod;
        }
    }

    printf("%lld\n", ans);
    return 0;
}

